-- Isolated fixtures; the final RESULT exception rolls the entire transaction back.
do $$
declare
 t uuid:='00000000-0000-0000-0000-00000000ab02';
 u uuid:='10000000-0000-0000-0000-00000000ab02';
 r uuid:='10000000-0000-0000-0000-00000000ab03';
 v uuid:='10000000-0000-0000-0000-00000000ab04';
 e uuid:='20000000-0000-0000-0000-00000000ab02';
 c uuid:='30000000-0000-0000-0000-00000000ab02';
 p uuid:='40000000-0000-0000-0000-00000000ab02';
 a uuid:='60000000-0000-0000-0000-00000000ab02';
 ct uuid:='50000000-0000-0000-0000-00000000ab02';
 n int;passes int:=0;fails text[]:='{}';snap jsonb;
begin
 perform set_config('request.jwt.claims','',true);
 insert into tenants(id,business_name,display_name,project_prefix,is_demo) values(t,'Appointment SQL acceptance','Appointment SQL','ASQ',true);
 update tenant_modules set enabled=true where tenant_id=t and module_id in('clients_projects','commercial');
 insert into tenant_memberships(tenant_id,user_id,email,role,status) values(t,u,'owner@asq.test','owner_admin','active'),(t,r,'rm@asq.test','resource_manager','active'),(t,v,'viewer@asq.test','employee','active');
 insert into employees(id,tenant_id,full_name,user_id) values(e,t,'SQL viewer',v);
 insert into clients(id,tenant_id,name) values(c,t,'SQL Client');
 insert into client_contacts(id,tenant_id,client_id,name) values(ct,t,c,'SQL Contact');
 insert into projects(id,tenant_id,name,status,start_date,planned_finish_date) values(p,t,'SQL Project','active','2026-11-10','2027-06-01');
 insert into project_team(tenant_id,project_id,employee_id,project_role) values(t,p,e,'viewer');
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 insert into project_appointments(id,tenant_id,project_id,contracting_client_id,invoicing_client_id,title,stages) values(a,t,p,c,c,'Tender','[{"name":"Tender","scope":"Tender only","starts_on":"2026-11-10","ends_on":"2026-12-01"}]');
 insert into project_appointments(tenant_id,project_id,contracting_client_id,invoicing_client_id,title) values(t,p,c,c,'Delivery');
 select count(*) into n from project_appointments where project_id=p;if n=2 then passes:=passes+1;else fails:=fails||'multiple engagements';end if;
 insert into client_commercial_defaults(tenant_id,client_id,terms) values(t,c,'{"payment_terms":"30 days"}');
 insert into appointment_commercials(tenant_id,appointment_id,terms,agreed_fee,defaults_confirmed) values(t,a,'{"payment_terms":"30 days"}',12500,true);
 update client_commercial_defaults set terms='{"payment_terms":"60 days"}' where client_id=c;
 select count(*) into n from appointment_commercials where appointment_id=a and terms->>'payment_terms'='30 days' and agreed_fee=12500 and defaults_confirmed;if n=1 then passes:=passes+1;else fails:=fails||'default silently overwrote';end if;
 select identity_snapshot into snap from project_appointments where id=a;
 update clients set name='Changed client' where id=c;
 select count(*) into n from project_appointments where id=a and identity_snapshot=snap;if n=1 then passes:=passes+1;else fails:=fails||'identity snapshot changed';end if;
 insert into appointment_contacts(tenant_id,appointment_id,contact_id,role) values(t,a,ct,'project');
 select count(*) into n from appointment_contact_details(a);if n=1 then passes:=passes+1;else fails:=fails||'contact link';end if;
 update project_appointments set scope='Edited' where id=a and version=1;
 update project_appointments set scope='Stale' where id=a and version=1;get diagnostics n=row_count;if n=0 then passes:=passes+1;else fails:=fails||'stale edit';end if;
 begin update project_appointments set stages='[{"name":"Tender","starts_on":"2026-12-01","ends_on":"2026-11-10"}]' where id=a;fails:=fails||'reversed stage dates';exception when others then if sqlerrm like 'INVALID_STAGE_DATES%' then passes:=passes+1;else fails:=fails||sqlerrm;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',r,'role','authenticated')::text,true);
 select count(*) into n from appointment_commercials where appointment_id=a;if n=0 then passes:=passes+1;else fails:=fails||'RM commercial disclosure';end if;
 select count(*) into n from client_commercial_defaults where client_id=c;if n=0 then passes:=passes+1;else fails:=fails||'RM defaults disclosure';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',v,'role','authenticated')::text,true);
 select count(*) into n from project_appointments where id=a;if n=1 then passes:=passes+1;else fails:=fails||'viewer read';end if;
 select count(*) into n from appointment_contact_details(a);if n=1 then passes:=passes+1;else fails:=fails||'viewer linked contacts';end if;
 select count(*) into n from client_contacts where id=ct;if n=0 then passes:=passes+1;else fails:=fails||'viewer whole CRM';end if;
 update project_appointments set scope='Viewer edit' where id=a;get diagnostics n=row_count;if n=0 then passes:=passes+1;else fails:=fails||'viewer wrote';end if;
 select count(*) into n from appointment_entity_options(t,p);if n=0 then passes:=passes+1;else fails:=fails||'viewer entity options';end if;
 perform set_config('request.jwt.claims',json_build_object('sub','10000000-0000-0000-0000-00000000ab05','role','authenticated')::text,true);
 select count(*) into n from project_appointments where id=a;if n=0 then passes:=passes+1;else fails:=fails||'outsider read';end if;
 select count(*) into n from appointment_contact_details(a);if n=0 then passes:=passes+1;else fails:=fails||'outsider contacts';end if;
 execute 'reset role';perform set_config('request.jwt.claims','',true);
 update tenant_modules set enabled=false where tenant_id=t and module_id='commercial';
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);execute 'set local role authenticated';
 select count(*) into n from appointment_commercials where appointment_id=a;if n=0 then passes:=passes+1;else fails:=fails||'commercial module off';end if;
 execute 'reset role';perform set_config('request.jwt.claims','',true);
 update tenant_modules set enabled=false where tenant_id=t and module_id='clients_projects';
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);execute 'set local role authenticated';
 select count(*) into n from project_appointments where id=a;if n=0 then passes:=passes+1;else fails:=fails||'core module off';end if;
 execute 'reset role';perform set_config('request.jwt.claims','',true);
 select count(*) into n from audit_log where tenant_id=t and record_table='project_appointments';if n>=3 then passes:=passes+1;else fails:=fails||'audit missing';end if;
 raise exception 'APPOINTMENTS RESULT passes=% fails=%',passes,fails;
end $$;